var CONTINUT_LOGICA={};
CONTINUT_LOGICA["teorema-goedel-incompletitudine-i"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice sistem formal consistent, recursiv axiomatizabil și capabil să reprezinte aritmetica elementară conține propoziții adevărate care nu pot fi demonstrate în sistem.</div>",formula_display:"∃P: P adevărată, dar ⊬P și ⊬¬P (în sistem consistent)",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"30\" y=\"30\" width=\"180\" height=\"130\" rx=\"10\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"120\" y=\"20\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8a3010\">Sistem formal T</text><circle cx=\"70\" cy=\"70\" r=\"14\" fill=\"none\" stroke=\"#8a3010\"/><text x=\"70\" y=\"75\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8a3010\">A</text><circle cx=\"120\" cy=\"100\" r=\"14\" fill=\"none\" stroke=\"#8a3010\"/><text x=\"120\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8a3010\">B</text><circle cx=\"80\" cy=\"130\" r=\"14\" fill=\"none\" stroke=\"#8a3010\"/><text x=\"80\" y=\"135\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8a3010\">C</text><text x=\"120\" y=\"185\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">propoziții demonstrabile</text><circle cx=\"230\" cy=\"95\" r=\"20\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"3\" stroke-dasharray=\"4 3\"/><text x=\"230\" y=\"90\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\">G</text><text x=\"230\" y=\"103\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">adevărată</text><line x1=\"160\" y1=\"95\" x2=\"210\" y2=\"95\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\"/><text x=\"230\" y=\"135\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">nedemonstrabilă în T</text></svg>",intuitiv_text:"Imaginează o cutie de reguli care hotărăște ce este adevărat. Scriem un bilet special: <span class=\"hl\">„Acest bilet nu poate fi dovedit de cutie.”</span> Dacă cutia reușește să-l dovedească, atunci cutia a dovedit ceva fals - e stricată. Dacă nu-l poate dovedi, biletul are dreptate și e adevărat, dar cutia nu poate demonstra asta niciodată. Așa arată Gödel că orice cutie de reguli suficient de puternică are un bilet pe care nu-l poate rezolva.",intuitiv_nota:"Kurt Gödel a publicat rezultatul în 1931, la doar 25 de ani, zdrobind programul lui Hilbert, care voia să fundamenteze toată matematica complet și consistent. E considerată una dintre cele mai importante realizări intelectuale ale secolului XX.",exercitii:[{"q":"Într-un sistem formal T, construim propoziția G care spune „G nu este demonstrabilă în T”. Explică pas cu pas ce înseamnă asta pentru T.","pasi":["G este o propoziție despre ea însăși, construită prin numerotare Gödel, exact ca o frază care vorbește despre propriul ei statut","Dacă T ar demonstra G, atunci T ar demonstra o propoziție care spune despre sine că nu poate fi demonstrată - contradicție internă","Dacă T nu demonstrează G, atunci ce spune G este adevărat (G chiar nu e demonstrabilă), deci G e un adevăr pe care T nu-l poate atinge"],"r":"✓ G este adevărată, dar T (dacă e consistent) nu o poate demonstra"},{"q":"Ce s-ar întâmpla dacă am adăuga G ca axiomă nouă la T, obținând un sistem nou T2=T+G?","pasi":["T2 poate acum demonstra G direct, pentru că G a devenit axiomă","Dar teorema lui Gödel se aplică din nou lui T2, care e tot un sistem consistent, recursiv axiomatizabil, capabil de aritmetică","T2 are propria sa propoziție G2, „G2 nu e demonstrabilă în T2”, la fel de nedemonstrabilă ca înainte"],"r":"✓ Problema reapare mereu - nu poți repara incompletitudinea adăugând o singură axiomă"},{"q":"Există sisteme formale care nu suferă de incompletitudinea lui Gödel?","pasi":["Da - sistemele prea slabe pentru a reprezenta aritmetica elementară (adunare, înmulțire, cuantificatori) scapă de teoremă","Exemplu: calculul propozițional simplu, fără cuantificatori peste numere, este complet și decidabil","Puterea de exprimare a aritmeticii este exact ce face incompletitudinea inevitabilă"],"r":"✓ Da, sisteme suficient de slabe pot fi complete - prețul e puterea de exprimare"},{"q":"Adevărat sau fals: teorema lui Gödel arată că matematica are contradicții.","pasi":["Fals - Gödel presupune consistența sistemului, nu arată contradicții","Teorema arată doar că, dacă sistemul e consistent, atunci e și incomplet - există adevăruri nedemonstrabile","Confuzia dintre incomplet și inconsistent este cea mai frecventă neînțelegere a teoremei"],"r":"✓ Fals - Gödel arată incompletitudine, nu inconsistență"},{"q":"De ce nu poate exista un program de calculator care verifică automat orice teoremă matematică adevărată?","pasi":["Un asemenea program ar corespunde unui sistem formal complet și decidabil pentru toată matematica","Gödel arată că orice sistem suficient de puternic pentru aritmetică are propoziții adevărate nedemonstrabile în el","Deci orice program de verificare automată va rata mereu unele adevăruri matematice, oricât de bine ar fi construit"],"r":"✓ Pentru că orice sistem suficient de puternic e incomplet - există adevăruri pe care niciun program nu le poate demonstra"}]};
CONTINUT_LOGICA["teorema-goedel-incompletitudine-ii"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Niciun sistem formal consistent care satisface condițiile teoremei I nu poate demonstra propria sa consistență.</div>",formula_display:"Consistent(T) ⊬ Consistent(T) (din T)",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"90\" y=\"60\" width=\"120\" height=\"70\" rx=\"8\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"150\" y=\"100\" text-anchor=\"middle\" font-size=\"16\" fill=\"#8a3010\">T</text><path d=\"M210 75 C 270 40, 270 150, 210 115\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"255\" y=\"95\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\">„Sunt consistent?”</text><line x1=\"235\" y1=\"75\" x2=\"255\" y2=\"115\" stroke=\"#8a3010\" stroke-width=\"3\"/><line x1=\"255\" y1=\"75\" x2=\"235\" y2=\"115\" stroke=\"#8a3010\" stroke-width=\"3\"/><text x=\"150\" y=\"155\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">T nu-și poate dovedi singur consistența</text></svg>",intuitiv_text:"Un sistem de reguli nu poate spune singur despre el însuși <span class=\"hl\">„eu sunt sigur, nu greșesc niciodată”</span>. E ca un copil care își verifică singur tema doar cu regulile pe care le-a folosit deja ca să facă tema - nu e o dovadă în care să te poți încrede complet. Ca să fii sigur că regulile tale nu au greșeli, ai nevoie de reguli din afara sistemului, nu doar de el însuși.",intuitiv_nota:"E o consecință directă a primei teoreme și a distrus speranța lui Hilbert într-un fundament absolut sigur al matematicii. Bertrand Russell a rezumat-o simplu: „Logica e mai complicată decât am crezut.”",exercitii:[{"q":"Presupune că un sistem T demonstrează chiar el propria propoziție Consistent(T). Ce spune a doua teoremă a lui Gödel despre această situație?","pasi":["A doua teoremă a lui Gödel spune că orice sistem consistent, care satisface condițiile primei teoreme, nu poate demonstra Consistent(T) despre el însuși","Dacă totuși T demonstrează Consistent(T), înseamnă că ipoteza de consistență a lui T este falsă, adică T este de fapt inconsistent","Un sistem inconsistent poate demonstra orice propoziție, inclusiv una falsă precum Consistent(T) despre un sistem contradictoriu"],"r":"✓ Dacă T se demonstrează consistent pe sine, T este de fapt inconsistent"},{"q":"Ce s-ar întâmpla dacă am folosi un sistem T2 mai puternic, în care demonstrăm Consistent(T1) pentru un sistem T1 mai slab?","pasi":["Acest lucru este posibil și se întâmplă des - de exemplu ZFC demonstrează Consistent(PA)","Dar teorema a doua se aplică din nou lui T2: T2 nu-și poate demonstra propria consistență, Consistent(T2)","Rămânem cu un lanț fără sfârșit: fiecare sistem are nevoie de unul și mai puternic pentru a-i valida consistența"],"r":"✓ Se obține un regres infinit de sisteme, fiecare validat doar din afara lui"},{"q":"Există sisteme formale care își pot demonstra propria consistență fără contradicție?","pasi":["Da - dar numai sisteme prea slabe pentru a reprezenta aritmetica elementară, deci care nu satisfac ipotezele teoremei","Un asemenea sistem slab nu poate exprima suficient de bine noțiunea de demonstrație pentru ca autoreferința lui Gödel să funcționeze","Prețul plătit este, ca și la prima teoremă, o putere de exprimare mult redusă"],"r":"✓ Doar sisteme prea slabe pentru aritmetică pot demonstra propria consistență"},{"q":"Adevărat sau fals: a doua teoremă a lui Gödel arată că nu putem ști niciodată dacă matematica este consistentă.","pasi":["Parțial adevărat, dar formulat prea tare - teorema arată doar că nu putem ști asta din interiorul aceluiași sistem","Putem avea încredere indirectă, din alte surse: consistență relativă față de un sistem mai puternic, sau argumente informale puternice","Teorema nu spune că matematica e inconsistentă, ci doar că certitudinea absolută, auto-demonstrată, este imposibilă"],"r":"✓ Fals ca enunț absolut - există certitudine relativă, doar nu una auto-demonstrată din interior"},{"q":"De ce un program de verificare a demonstrațiilor nu se poate auto-certifica drept complet sigur?","pasi":["Un asemenea program se bazează pe un sistem formal de reguli pentru a verifica demonstrații matematice, la fel ca T în teoremă","Dacă acest sistem este suficient de puternic pentru aritmetică, el nu-și poate demonstra propria consistență folosind doar propriile reguli","Practic, încrederea în astfel de programe vine din verificare externă, testare îndelungată și argumente meta-matematice, nu dintr-o auto-certificare formală"],"r":"✓ Pentru că orice astfel de sistem suficient de puternic nu-și poate valida singur consistența"}]};
CONTINUT_LOGICA["teorema-lui-cantor-cardinale"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Cardinalul mulțimii putere a oricărei mulțimi A este strict mai mare decât cardinalul lui A: |𝒫(A)| &gt; |A|.</div>",formula_display:"|𝒫(A)| &gt; |A| pentru orice mulțime A",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"70\" cy=\"100\" r=\"50\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"70\" y=\"40\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8a3010\">A</text><circle cx=\"55\" cy=\"85\" r=\"4\" fill=\"#8a3010\"/><circle cx=\"85\" cy=\"85\" r=\"4\" fill=\"#8a3010\"/><circle cx=\"70\" cy=\"115\" r=\"4\" fill=\"#8a3010\"/><circle cx=\"230\" cy=\"100\" r=\"75\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"230\" y=\"15\" text-anchor=\"middle\" font-size=\"13\" fill=\"#c8922a\">𝒫(A)</text><circle cx=\"190\" cy=\"70\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"220\" cy=\"60\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"250\" cy=\"65\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"270\" cy=\"90\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"270\" cy=\"120\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"240\" cy=\"140\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"200\" cy=\"130\" r=\"4\" fill=\"#c8922a\"/><circle cx=\"230\" cy=\"105\" r=\"4\" fill=\"#c8922a\"/><line x1=\"122\" y1=\"100\" x2=\"150\" y2=\"100\" stroke=\"#8a3010\" stroke-width=\"2\" marker-end=\"url(#arrcantor)\"/><text x=\"150\" y=\"90\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">mereu mai multe</text><defs><marker id=\"arrcantor\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8a3010\"/></marker></defs></svg>",intuitiv_text:"Ai o cutie cu jucării. Poți face liste de jucării din cutie: o listă goală, liste cu o jucărie, cu două, cu toate... <span class=\"hl\">Aceste liste sunt mai multe decât jucăriile înseși</span>. Oricât de mare ar fi o mulțime, mulțimea tuturor grupurilor ei este și mai mare. Așa există infinituri mai mari decât alte infinituri.",intuitiv_nota:"Georg Cantor a ajuns la acest rezultat în 1891, prin argumentul diagonal, după ce pusese bazele teoriei mulțimilor și demonstrase că ℝ este „mai mare” decât ℕ. Contemporanii l-au ridiculizat, dar postum a fost recunoscut ca un geniu.",exercitii:[{"q":"Calculează |𝒫(A)| pentru A={1,2,3} și verifică direct inegalitatea |𝒫(A)|&gt;|A|.","pasi":["Mulțimea putere 𝒫(A) conține toate submulțimile lui A: mulțimea vidă, cele cu un element, cu două, și A însăși - în total 2³=8 submulțimi","|A|=3, iar |𝒫(A)|=8","8&gt;3, deci inegalitatea lui Cantor se verifică direct în acest caz mic"],"r":"✓ |𝒫(A)|=8 &gt; |A|=3"},{"q":"Ce s-ar întâmpla dacă ar exista o bijecție f între o mulțime A și mulțimea ei putere 𝒫(A)?","pasi":["Construim mulțimea B={x∈A : x∉f(x)}, formată din elementele care nu aparțin propriei imagini prin f","B este o submulțime a lui A, deci ar trebui să existe un element b∈A cu f(b)=B, pentru că f e presupusă bijecție","Dar atunci b∈B ↔ b∉f(b)=B, o contradicție logică directă (exact structura paradoxului lui Russell)"],"r":"✓ Se obține o contradicție - deci o asemenea bijecție nu poate exista niciodată"},{"q":"Ce se întâmplă cu inegalitatea lui Cantor pentru mulțimea vidă, A=∅?","pasi":["𝒫(∅) conține exact o submulțime: mulțimea vidă însăși, deci |𝒫(∅)|=1","|∅|=0","1&gt;0, deci inegalitatea se verifică inclusiv în acest caz limită"],"r":"✓ Se verifică și pentru A=∅: 1 &gt; 0"},{"q":"Adevărat sau fals: ℕ, ℤ și ℚ au toate cardinalul ℵ₀, deci teorema lui Cantor arată că fiecare are o mulțime putere strict mai mare.","pasi":["Adevărat - deși ℕ, ℤ și ℚ par foarte diferite ca mărime intuitivă, toate sunt numărabile, cu același cardinal ℵ₀","Teorema lui Cantor se aplică oricărei mulțimi, inclusiv acestora: 𝒫(ℕ) are cardinal 2^ℵ₀, strict mai mare decât ℵ₀","Acest 2^ℵ₀ se dovedește a fi exact cardinalul lui ℝ, numărul real"],"r":"✓ Adevărat - toate cele trei au 𝒫 strict mai mare, egal cu cardinalul lui ℝ"},{"q":"De ce nu poate exista mulțimea tuturor mulțimilor în teoria axiomatică a mulțimilor?","pasi":["Dacă ar exista o mulțime universală U care conține toate mulțimile, atunci 𝒫(U) ar fi tot o mulțime, deci ar fi conținută în U","Dar teorema lui Cantor spune că |𝒫(U)|&gt;|U| întotdeauna, deci 𝒫(U) nu poate fi o submulțime a lui U de aceeași mărime sau mai mică","Contradicția arată că nicio mulțime nu poate conține totul - de aceea teoria axiomatică a mulțimilor interzice o asemenea construcție"],"r":"✓ Pentru că ar contrazice teorema lui Cantor: 𝒫(U) ar trebui să fie mai mare decât U, dar și conținută în U"}]};
CONTINUT_LOGICA["problema-halting"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Nu există un algoritm (mașină Turing) universal HALT care să decidă pentru orice program P și input I dacă P(I) se oprește sau rulează la infinit.</div>",formula_display:"∄HALT: HALT(P,I)=DA ↔ P(I) se oprește",diagrama:"<svg viewBox=\"0 0 320 190\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"26\" height=\"26\" fill=\"none\" stroke=\"#8a3010\"/><rect x=\"46\" y=\"20\" width=\"26\" height=\"26\" fill=\"none\" stroke=\"#8a3010\"/><rect x=\"72\" y=\"20\" width=\"26\" height=\"26\" fill=\"none\" stroke=\"#8a3010\"/><rect x=\"98\" y=\"20\" width=\"26\" height=\"26\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><rect x=\"124\" y=\"20\" width=\"26\" height=\"26\" fill=\"none\" stroke=\"#8a3010\"/><rect x=\"150\" y=\"20\" width=\"26\" height=\"26\" fill=\"none\" stroke=\"#8a3010\"/><polygon points=\"111,52 121,66 101,66\" fill=\"#c8922a\"/><text x=\"85\" y=\"14\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">bandă mașină Turing</text><rect x=\"115\" y=\"90\" width=\"90\" height=\"40\" rx=\"8\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"160\" y=\"114\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8a3010\">HALT?</text><text x=\"60\" y=\"150\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">se oprește ✓</text><text x=\"260\" y=\"150\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">rulează infinit ↻</text><line x1=\"115\" y1=\"110\" x2=\"70\" y2=\"140\" stroke=\"#8a3010\"/><line x1=\"205\" y1=\"110\" x2=\"250\" y2=\"140\" stroke=\"#8a3010\"/><text x=\"160\" y=\"175\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\">niciun algoritm nu decide mereu corect</text></svg>",intuitiv_text:"Imaginează un robot care citește o carte foarte lungă și trebuie să ghicească dacă lectura se va termina vreodată sau va continua la nesfârșit. Turing a arătat că <span class=\"hl\">nu poate exista un robot-judecător perfect, care să ghicească mereu corect, pentru orice carte și orice cititor</span>. Unele bucle nu pot fi prezise dinainte - trebuie pur și simplu așteptat, uneori la infinit.",intuitiv_nota:"Alan Turing a demonstrat rezultatul în 1936, printr-un paradox autoreflexiv. Cu el a pus bazele informaticii teoretice, arătând că există probleme algoritmice pur și simplu imposibil de rezolvat.",exercitii:[{"q":"Presupunând că există un program HALT(P,I) care decide corect dacă orice program P se oprește pe orice input I, cum construim o contradicție?","pasi":["Construim un nou program D(P), care rulează HALT(P,P): dacă răspunsul e „se oprește”, D intră într-o buclă infinită; dacă e „nu se oprește”, D se oprește imediat","Rulăm apoi D(D): dacă D(D) se oprește, atunci HALT(D,D) a răspuns „nu se oprește”, dar tocmai am arătat că D(D) se oprește - contradicție","Dacă D(D) nu se oprește, HALT(D,D) a răspuns „se oprește”, dar D(D) tocmai nu s-a oprit - din nou contradicție"],"r":"✓ Ambele cazuri dau contradicție, deci HALT nu poate exista"},{"q":"Ce s-ar întâmpla dacă am limita problema doar la programe fără bucle while sau recursivitate, cu un număr fix de pași?","pasi":["Pentru asemenea programe simple, foarte limitate, numărul de pași posibili e mărginit dinainte, deci putem întotdeauna decide dacă se opresc, rulând pur și simplu programul","Problema opririi devine decidabilă exact pentru că am eliminat capacitatea de a construi acel D(D) autoreferențial","Nedecidabilitatea vine deci chiar din puterea de calcul completă (bucle, recursivitate), nu e o proprietate universală a oricărui program"],"r":"✓ Ar deveni decidabilă - dar am pierde puterea de calcul generală (Turing-completă)"},{"q":"Există programe P și inputuri I pentru care poți decide, cu certitudine, dacă se opresc sau nu?","pasi":["Da - Halting Problem spune că nu există un algoritm universal, care să funcționeze pentru orice pereche (P,I)","Pentru cazuri particulare simple (un program fără bucle, sau o buclă cu contor fix), putem decide direct, analizând codul","Nedecidabilitatea e despre imposibilitatea unei soluții generale, nu despre imposibilitatea oricărei soluții particulare"],"r":"✓ Da, pentru cazuri particulare simple se poate decide - doar soluția generală, universală, e imposibilă"},{"q":"Adevărat sau fals: problema opririi este semi-decidabilă, adică putem întotdeauna confirma când un program se oprește, chiar dacă nu putem întotdeauna confirma că nu se oprește.","pasi":["Adevărat - dacă P(I) chiar se oprește, putem afla asta simplu, rulând programul până se oprește și observând acest fapt","Dacă P(I) nu se oprește niciodată, rulându-l pur și simplu nu vom ști niciodată sigur dacă nu s-a oprit încă sau nu se va opri deloc","De-asta se spune semi-decidabil: putem confirma un răspuns, dar nu îl putem infirma cu certitudine în timp finit"],"r":"✓ Adevărat - confirmăm oprirea, dar nu putem confirma niciodată bucla infinită cu certitudine"},{"q":"De ce mediile de dezvoltare software nu pot avea un buton care detectează toate buclele infinite din codul tău?","pasi":["Un asemenea buton ar corespunde exact unui algoritm HALT universal, despre care Turing a demonstrat că nu poate exista","IDE-urile moderne pot detecta euristic unele bucle infinite simple, dar nu garantat, pentru orice program posibil","E o consecință directă și foarte practică a problemei opririi, resimțită zilnic de orice programator care depanează cod blocat"],"r":"✓ Pentru că ar rezolva Halting Problem, ceea ce s-a demonstrat imposibil - doar detecție parțială, euristică, e posibilă"}]};
CONTINUT_LOGICA["axioma-alegerii"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Pentru orice familie non-vidă de mulțimi non-vide, există o funcție f (funcție de alegere) care selectează câte un element din fiecare mulțime din familie.</div>",formula_display:"∀{Aα}: Aα≠∅ → ∃f: f(Aα)∈Aα",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\"><ellipse cx=\"60\" cy=\"60\" rx=\"40\" ry=\"30\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><circle cx=\"45\" cy=\"55\" r=\"5\" fill=\"#8a3010\"/><circle cx=\"65\" cy=\"50\" r=\"5\" fill=\"#8a3010\"/><circle cx=\"75\" cy=\"70\" r=\"5\" fill=\"#c8922a\"/><ellipse cx=\"160\" cy=\"60\" rx=\"40\" ry=\"30\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><circle cx=\"145\" cy=\"70\" r=\"5\" fill=\"#c8922a\"/><circle cx=\"170\" cy=\"50\" r=\"5\" fill=\"#8a3010\"/><circle cx=\"180\" cy=\"65\" r=\"5\" fill=\"#8a3010\"/><ellipse cx=\"260\" cy=\"60\" rx=\"40\" ry=\"30\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><circle cx=\"245\" cy=\"55\" r=\"5\" fill=\"#8a3010\"/><circle cx=\"270\" cy=\"50\" r=\"5\" fill=\"#8a3010\"/><circle cx=\"255\" cy=\"72\" r=\"5\" fill=\"#c8922a\"/><text x=\"160\" y=\"15\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8a3010\">mulțimi (poate infinit de multe)</text><line x1=\"75\" y1=\"70\" x2=\"145\" y2=\"70\" stroke=\"#c8922a\" stroke-dasharray=\"3 2\"/><line x1=\"145\" y1=\"70\" x2=\"255\" y2=\"72\" stroke=\"#c8922a\" stroke-dasharray=\"3 2\"/><text x=\"160\" y=\"130\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c8922a\">f alege câte un element din fiecare</text></svg>",intuitiv_text:"Ai multe pungi cu bomboane, poate chiar infinit de multe pungi. <span class=\"hl\">Poți alege câte o bomboană din fiecare pungă, chiar dacă nu îți spun o regulă clară cum să alegi</span>. Pentru câteva pungi e ușor, dar pentru infinit de multe, matematicienii au avut nevoie de o axiomă specială care să garanteze că alegerea e mereu posibilă.",intuitiv_nota:"Formulată de Zermelo în 1904, axioma s-a dovedit independentă de ZF - Gödel a arătat asta în 1938, Cohen în 1963. E echivalentă cu Lema lui Zorn, cu Teorema Bine-Ordonării și cu teorema lui Tychonoff.",exercitii:[{"q":"Ai trei mulțimi nevide: A={2,4}, B={7}, C={1,3,9}. Construiește explicit o funcție de alegere f pentru familia {A,B,C}.","pasi":["O funcție de alegere trebuie să selecteze exact un element din fiecare mulțime din familie","Putem alege, de exemplu, f(A)=2, f(B)=7, f(C)=1 - orice alegere consistentă e validă","Pentru colecții finite ca aceasta, funcția de alegere se poate construi explicit, fără a avea nevoie de axioma alegerii"],"r":"✓ De exemplu f(A)=2, f(B)=7, f(C)=1 - construită explicit, fără axioma alegerii"},{"q":"Ce s-ar întâmpla dacă am renunța complet la axioma alegerii în matematică?","pasi":["Am pierde rezultate importante: existența unei baze pentru orice spațiu vectorial, teorema bine-ordonării, teorema Tychonoff din topologie","Unele construcții patologice, cum e paradoxul Banach-Tarski, ar dispărea, dar și multe rezultate utile din analiza funcțională","Matematica ar deveni, în anumite privințe, mai constructivă dar și mult mai săracă în rezultate generale despre mulțimi infinite arbitrare"],"r":"✓ S-ar pierde teoreme importante, dar și construcții contraintuitive precum paradoxul Banach-Tarski"},{"q":"Pentru o familie numărabilă de mulțimi finite nevide, e nevoie de axioma alegerii completă pentru a construi o funcție de alegere?","pasi":["Nu neapărat - există o versiune mai slabă, axioma alegerii numărabile, suficientă pentru multe cazuri numărabile","Pentru mulțimi cu o structură suplimentară (de exemplu submulțimi de numere naturale, cu element minim), se poate alege explicit cel mai mic element, fără nicio axiomă suplimentară","Nevoia axiomei alegerii complete apare abia la familii genuin arbitrare, necontabile, fără nicio structură suplimentară de selecție"],"r":"✓ Nu întotdeauna - depinde de structura suplimentară a mulțimilor; varianta completă e necesară doar în cazul general"},{"q":"Adevărat sau fals: axioma alegerii poate fi demonstrată din celelalte axiome ale teoriei mulțimilor (ZF).","pasi":["Fals - Kurt Gödel (1938) a arătat că AC este consistentă cu ZF (nu contrazice celelalte axiome)","Paul Cohen (1963) a arătat, complementar, că negația lui AC este de asemenea consistentă cu ZF","Împreună, aceste rezultate arată că AC este independentă de ZF: nu poate fi nici demonstrată, nici infirmată din celelalte axiome"],"r":"✓ Fals - AC este independentă de ZF (Gödel și Cohen)"},{"q":"De ce alegerea unei perechi de șosete dintr-un număr infinit de perechi identice e un bun exemplu pentru necesitatea axiomei alegerii?","pasi":["Bertrand Russell a dat un exemplu înrudit: din infinit de perechi de pantofi (stânga/dreapta diferite) poți alege mereu piciorul stâng - o regulă explicită","Din infinit de perechi de șosete identice, nu există nicio trăsătură care să distingă un element de celălalt în fiecare pereche - nicio regulă explicită de alegere","Axioma alegerii garantează totuși că o funcție de selecție există, chiar și fără o regulă explicită de distincție - exact ca la șosete"],"r":"✓ Pentru că, spre deosebire de pantofi, șosetele identice nu oferă nicio regulă explicită de alegere - AC garantează totuși că o alegere există"}]};
CONTINUT_LOGICA["teorema-compactatii"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> O teorie T de ordinul I este satisfiabilă (are model) dacă și numai dacă orice subset finit al lui T este satisfiabil.</div>",formula_display:"T satisfiabilă ↔ fiecare T₀⊆_finit T satisfiabilă",diagrama:"<svg viewBox=\"0 0 320 190\" xmlns=\"http://www.w3.org/2000/svg\"><ellipse cx=\"160\" cy=\"80\" rx=\"140\" ry=\"60\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\" stroke-dasharray=\"5 3\"/><text x=\"160\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8a3010\">T (teorie, posibil infinită)</text><circle cx=\"90\" cy=\"70\" r=\"24\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"90\" y=\"74\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">T0 ✓</text><circle cx=\"160\" cy=\"95\" r=\"24\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"160\" y=\"99\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">T1 ✓</text><circle cx=\"230\" cy=\"65\" r=\"24\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"230\" y=\"69\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">T2 ✓</text><text x=\"160\" y=\"150\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">fiecare subset finit are model</text><line x1=\"160\" y1=\"155\" x2=\"160\" y2=\"172\" stroke=\"#8a3010\" stroke-width=\"2\" marker-end=\"url(#arrc)\"/><defs><marker id=\"arrc\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8a3010\"/></marker></defs><text x=\"160\" y=\"185\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8a3010\">T are model</text></svg>",intuitiv_text:"Dacă vrei să știi dacă o poveste foarte, foarte lungă (poate infinită) are sens, e destul să verifici pe rând fiecare bucățică mică din ea. <span class=\"hl\">Dacă toate bucățile mici se potrivesc fără contradicție, atunci toată povestea, oricât de lungă, se potrivește și ea</span>.",intuitiv_nota:"Gödel a demonstrat-o în 1930, pentru logica de ordinul întâi, iar consecințele ei sunt surprinzătoare: printre altele, arată că există modele non-standard ale aritmeticii, cu „numere infinite”.",exercitii:[{"q":"Fie T o teorie și P o propoziție cu T∪{¬P} nesatisfiabilă. Ce ne spune teorema compacității despre relația dintre T și P?","pasi":["T∪{¬P} nesatisfiabilă înseamnă, conform teoremei compacității, că are un subset finit nesatisfiabil","Acest subset finit conține un număr finit de propoziții din T, plus ¬P","Nesatisfiabilitatea acestui subset finit înseamnă exact că T⊨P: P este o consecință logică a lui T"],"r":"✓ T⊨P (P urmează logic din T)"},{"q":"Ce s-ar întâmpla dacă am adăuga la aritmetica Peano (PA) o mulțime infinită de axiome noi, {c&gt;0, c&gt;1, c&gt;2, ...}, pentru o constantă nouă c?","pasi":["Fiecare subset finit al noii teorii conține doar un număr finit de condiții c&gt;n - putem alege oricând c suficient de mare pentru a le satisface pe toate","Deci fiecare subset finit este satisfiabil, iar prin teorema compacității întreaga teorie infinită este și ea satisfiabilă","Rezultă un model al PA în care c se comportă ca un număr infinit, mai mare decât orice număr natural standard - un model non-standard"],"r":"✓ Se obține un model non-standard al PA, cu un element c mai mare decât orice număr natural"},{"q":"Teorema compacității se aplică și pentru logica de ordinul al doilea?","pasi":["Nu - logica de ordinul al doilea, care poate cuantifica peste mulțimi de elemente, nu satisface teorema compacității în general","Diferența esențială dintre ordinul I și ordinul II stă exact aici: puterea de exprimare suplimentară a ordinului II se plătește prin pierderea unor proprietăți metalogice utile, precum compacitatea","De aceea logicienii preferă adesea logica de ordinul întâi pentru studiul fundamentelor"],"r":"✓ Nu, compacitatea este specifică logicii de ordinul întâi"},{"q":"Adevărat sau fals: teorema compacității implică faptul că o teorie infinită nesatisfiabilă trebuie să aibă un subset infinit nesatisfiabil ca dovadă minimă a contradicției.","pasi":["Fals - exact opusul este adevărat: dacă o teorie infinită e nesatisfiabilă, există deja un subset finit nesatisfiabil","Chiar asta spune teorema compacității: nesatisfiabilitatea se vede întotdeauna pe un fragment finit, niciodată doar la infinit","Practic, orice contradicție logică poate fi urmărită, în principiu, printr-un număr finit de pași de deducție"],"r":"✓ Fals - contradicția se vede mereu pe un subset finit, nu necesită un subset infinit"},{"q":"Cum se aplică teorema compacității la colorarea cu k culori a unui graf infinit?","pasi":["Un graf infinit G este k-colorabil dacă și numai dacă fiecare subgraf finit al lui G este k-colorabil - o consecință directă a compacității","Codificăm colorarea ca o teorie logică: câte o propoziție pentru fiecare vârf și culoare posibilă, plus reguli care interzic culori identice pentru vârfuri adiacente","Dacă fiecare bucată finită a graficului poate fi colorată corect, compacitatea garantează că întregul graf infinit poate fi colorat corect, dintr-o dată"],"r":"✓ G infinit e k-colorabil dacă și numai dacă fiecare subgraf finit al său e k-colorabil"}]};
CONTINUT_LOGICA["teorema-cook-levin"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Problema satisfiabilității formulelor booleene în formă normal conjunctivă (SAT) este NP-completă: orice problemă NP se reduce polinomial la SAT.</div>",formula_display:"SAT este NP-complet",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"160\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8a3010\">orice problemă din NP</text><rect x=\"15\" y=\"30\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"50\" y=\"50\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">TSP</text><rect x=\"125\" y=\"30\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"160\" y=\"50\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a3010\">colorare grafuri</text><rect x=\"235\" y=\"30\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"270\" y=\"50\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">knapsack</text><line x1=\"50\" y1=\"60\" x2=\"140\" y2=\"100\" stroke=\"#8a3010\" stroke-width=\"1.5\"/><line x1=\"160\" y1=\"60\" x2=\"160\" y2=\"100\" stroke=\"#8a3010\" stroke-width=\"1.5\"/><line x1=\"270\" y1=\"60\" x2=\"180\" y2=\"100\" stroke=\"#8a3010\" stroke-width=\"1.5\"/><rect x=\"110\" y=\"100\" width=\"100\" height=\"45\" rx=\"8\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"3\"/><text x=\"160\" y=\"120\" text-anchor=\"middle\" font-size=\"14\" fill=\"#c8922a\">SAT</text><text x=\"160\" y=\"137\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">solver universal</text><line x1=\"160\" y1=\"145\" x2=\"160\" y2=\"170\" stroke=\"#8a3010\" stroke-width=\"2\" marker-end=\"url(#arrcl)\"/><defs><marker id=\"arrcl\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8a3010\"/></marker></defs><text x=\"160\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">rezolvi SAT rapid → rezolvi tot NP rapid</text></svg>",intuitiv_text:"Imaginează multe jocuri de puzzle diferite: cel mai scurt traseu turistic, colorarea unei hărți cu puține culori, umplerea unui rucsac cu comori. <span class=\"hl\">Toate aceste jocuri, oricât de diferite par, pot fi transformate într-un singur joc: să bifezi ADEVĂRAT sau FALS niște cutii, astfel încât toate regulile scrise cu ȘI/SAU să fie respectate</span>. Acest joc unic se numește SAT. Dacă cineva ar găsi un truc rapid și garantat pentru SAT, ar rezolva dintr-o dată toate celelalte puzzle-uri, oricât de complicate ar părea.",intuitiv_nota:"Cook și Levin au ajuns la acest rezultat independent, în 1971 și respectiv 1973, punând bazele teoriei NP-completitudinii. De atunci, sute de probleme practice - de la TSP la colorarea grafurilor și knapsack - au fost dovedite NP-complete prin reducere la SAT.",exercitii:[{"q":"Formula φ=(A∨B)∧(¬A∨¬B) are doar două variabile. Găsește o atribuire care o satisface și explică ce înseamnă asta pentru SAT.","pasi":["Formula cere ca cel puțin una dintre A, B să fie adevărată (prima paranteză) și cel puțin una dintre negațiile lor să fie adevărată (a doua paranteză).","Încercăm A=adevărat, B=fals: prima paranteză (A∨B) e adevărată pentru că A e adevărat, iar a doua (¬A∨¬B) e adevărată pentru că ¬B e adevărat.","Am găsit o atribuire care satisface toate clauzele simultan, deci φ este satisfiabilă - exact tipul de întrebare pe care SAT o pune pentru orice formulă booleană."],"r":"✓ φ este satisfiabilă, de exemplu cu A=adevărat și B=fals."},{"q":"Ce s-ar întâmpla dacă cineva ar descoperi mâine un algoritm care rezolvă SAT în timp polinomial, pentru orice formulă, oricât de mare?","pasi":["Deoarece orice problemă din NP se poate transforma (reduce) polinomial în SAT, un algoritm rapid pentru SAT ar putea fi folosit pentru a rezolva rapid și acele probleme.","Traseul cel mai scurt al unui comis-voiajor, colorarea optimă a unei hărți, umplerea unui rucsac cu obiecte valoroase - toate ar deveni rezolvabile eficient, prin transformare în SAT.","Aceasta ar însemna P=NP, iar sisteme criptografice actuale, bazate pe faptul că unele probleme sunt greu de rezolvat dar ușor de verificat, s-ar prăbuși."],"r":"✓ S-ar rezolva eficient toate problemele NP deodată, inclusiv prăbușirea criptografiei actuale."},{"q":"Formula ψ=A∧¬A conține o singură variabilă. Este ea satisfiabilă? Ce arată acest exemplu simplu despre SAT?","pasi":["Pentru ca ψ să fie adevărată, A ar trebui să fie simultan adevărat (din A) și fals (din ¬A), ceea ce este imposibil pentru orice atribuire.","Nicio alegere a valorii lui A nu poate satisface ambele condiții deodată, deci ψ este nesatisfiabilă.","Acest exemplu mic arată că nu orice formulă din SAT are răspuns DA - unele sunt contradicții pure, iar recunoașterea acestui lucru face parte din problema SAT."],"r":"✓ ψ este nesatisfiabilă - nicio atribuire nu poate face A adevărat și fals în același timp."},{"q":"Adevărat sau fals: faptul că SAT este NP-complet înseamnă că orice formulă SAT este greu de verificat.","pasi":["Fals - NP-completitudinea lui SAT ține de cât de greu e să găsești o soluție, nu de cât de greu e s-o verifici pe una deja propusă.","Odată ce cineva propune o atribuire de valori pentru variabile, verificarea dacă ea satisface formula se face rapid, în timp polinomial, verificând fiecare clauză pe rând.","Dificultatea reală a SAT stă în a găsi acea atribuire printre exponențial de multe posibilități, nu în a confirma una deja găsită."],"r":"✓ Fals - verificarea unei soluții propuse este rapidă; greu este să găsești soluția."},{"q":"De ce firmele care proiectează procesoare și circuite electronice folosesc solvere SAT pentru a verifica automat corectitudinea unui circuit?","pasi":["Corectitudinea unui circuit electronic poate fi scrisă ca o formulă logică uriașă, cu o clauză pentru fiecare comportament dorit sau interzis al circuitului.","Un solver SAT modern, deși rezolvă în principiu o problemă NP-completă, folosește euristici puternice care merg foarte repede pe multe circuite reale, întâlnite în practică.","Astfel, o problemă teoretic foarte grea în cazul general devine, prin instrumente SAT bine construite, o unealtă zilnică pentru verificarea automată a hardware-ului."],"r":"✓ Pentru că, deși SAT e NP-complet în general, solverele moderne rezolvă rapid majoritatea cazurilor practice întâlnite în circuite reale."}]};
CONTINUT_LOGICA["teorema-lui-lowenheim-skolem"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă o teorie de ordinul întâi T are un model infinit, atunci T are modele de orice cardinalitate infinită - atât mai mici (versiunea descendentă), cât și mai mari (versiunea ascendentă), cu restricția ca noul cardinal să fie cel puțin egal cu cardinalul limbajului lui T.</div>",formula_display:"T are model infinit → T are model de orice cardinal infinit κ≥|L|",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">aceeași teorie T are modele de orice mărime infinită</text><circle cx=\"150\" cy=\"118\" r=\"80\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/><circle cx=\"150\" cy=\"118\" r=\"55\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><circle cx=\"150\" cy=\"118\" r=\"30\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"150\" y=\"122\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">T</text><text x=\"150\" y=\"93\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a3010\">model numărabil</text><text x=\"150\" y=\"68\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a3010\">model mai mare</text><text x=\"150\" y=\"43\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">model și mai mare...</text><text x=\"150\" y=\"192\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">T nu poate fixa mărimea propriilor modele</text></svg>",intuitiv_text:"Ai o cutie de construcție (o teorie T) cu instrucțiuni de asamblare. Aceleași instrucțiuni pot construi un turn mic, din puține piese, sau un turn foarte mare, din multe piese - instrucțiunile nu spun niciodată exact câte piese trebuie folosite. <span class=\"hl\">La fel, o teorie logică de ordinul întâi nu poate „obliga” lumea ei să aibă o singură mărime</span>: dacă are o lume infinită, are și lumi infinite de orice altă mărime, mai mici sau mai mari.",intuitiv_nota:"Leopold Löwenheim (1915) a demonstrat versiunea descendentă; Thoralf Skolem (1920) a generalizat rezultatul și a formulat paradoxul care îi poartă numele. Rezultatul arată o limită fundamentală a logicii de ordinul întâi: nu poate distinge complet între cardinalități infinite diferite.",exercitii:[{"q":"ZFC (dacă este consistentă) are un model infinit. Explică, pas cu pas, de ce teorema Löwenheim-Skolem garantează și un model numărabil pentru ZFC.","pasi":["ZFC este o teorie de ordinul întâi, scrisă într-un limbaj cu un număr numărabil de simboluri, iar prin ipoteză are cel puțin un model infinit.","Versiunea descendentă a teoremei Löwenheim-Skolem spune că, dintr-un model infinit al unei teorii de ordinul întâi, se poate extrage un submodel elementar echivalent de cardinalitate egală cu cardinalul limbajului, deci numărabil.","Rezultă că, oricât de „mare” ar fi modelul inițial al ZFC, există garantat și un model numărabil al aceleiași teorii, cu exact aceleași propoziții adevărate."],"r":"✓ Da, există garantat un model numărabil al ZFC, dacă ZFC are vreun model."},{"q":"Ce s-ar întâmpla dacă am încerca să scriem o teorie de ordinul întâi T care să aibă un singur model infinit posibil, până la izomorfism, indiferent de cardinalitate?","pasi":["Dacă T are măcar un model infinit, teorema Löwenheim-Skolem (versiunea ascendentă și descendentă) garantează automat modele de orice cardinalitate infinită posibilă, nu doar de una singură.","Deci T nu poate „forța” un model unic infinit prin mijloacele logicii de ordinul întâi, oricât de multe axiome am adăuga, atâta timp cât rămânem de ordinul întâi.","Încercarea ar eșua mereu în același fel: pentru fiecare cardinalitate infinită ar exista un model diferit al lui T, deci T nu poate fi categorică în sensul dorit."],"r":"✓ Încercarea ar eșua mereu - T ar avea automat modele de orice cardinalitate infinită, nu unul singur."},{"q":"ZFC demonstrează că există mulțimi nenumărabile (de exemplu mulțimea numerelor reale), dar are și un model numărabil. Este aceasta o contradicție reală?","pasi":["Nu este o contradicție - „nenumărabilă” înseamnă, din perspectiva modelului, că nu există în interiorul modelului nicio bijecție între acea mulțime și numerele naturale.","Modelul numărabil, privit din exterior, are într-adevăr doar numărabil de multe elemente, dar bijecția care ar arăta asta pur și simplu nu este unul dintre elementele modelului.","Acesta este chiar paradoxul lui Skolem: „numărabil” și „nenumărabil” devin noțiuni relative la modelul din care le privești, nu proprietăți absolute."],"r":"✓ Nu este o contradicție - este paradoxul lui Skolem, o relativizare a noțiunii de „nenumărabil” la model."},{"q":"Adevărat sau fals: aritmetica Peano de ordinul întâi (PA) are doar modelul standard ℕ.","pasi":["Fals - PA are un model infinit (ℕ însuși), deci teorema Löwenheim-Skolem ascendentă garantează modele de orice cardinalitate infinită mai mare.","Există așadar modele nenumărabile ale PA, numite modele non-standard, care conțin, pe lângă numerele naturale obișnuite, și elemente „infinite” suplimentare.","Aceste modele non-standard satisfac exact aceleași axiome PA ca și ℕ, dar au o structură diferită, mai bogată."],"r":"✓ Fals - PA are și modele non-standard, de orice cardinalitate infinită mai mare decât ℕ."},{"q":"De ce logica de ordinul al doilea, folosită uneori în specificarea formală a sistemelor software, nu suferă de aceeași „instabilitate” a mărimii modelelor ca logica de ordinul întâi?","pasi":["Logica de ordinul al doilea poate cuantifica direct peste mulțimi de elemente, nu doar peste elemente individuale, ceea ce îi permite să exprime axiome de categoricitate imposibil de scris în ordinul întâi.","De exemplu, axioma de inducție completă din aritmetică poate fi scrisă ca o singură propoziție de ordinul al doilea, fixând astfel structura modelului mult mai strict.","În schimb, logica de ordinul întâi, folosită de majoritatea instrumentelor de verificare automată pentru că e mult mai ușor de manevrat algoritmic, rămâne mereu supusă teoremei Löwenheim-Skolem."],"r":"✓ Pentru că are puterea de exprimare suplimentară (cuantificare peste mulțimi) care lipsește logicii de ordinul întâi."}]};
CONTINUT_LOGICA["principiul-inductiei-matematice"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie P(n) o proprietate definită pentru numere naturale. Dacă P(0) este adevărată (pasul de bază) și, pentru orice n, P(n) implică P(n+1) (pasul inductiv), atunci P(n) este adevărată pentru toate numerele naturale n.</div>",formula_display:"P(0) ∧ ∀n(P(n)→P(n+1)) → ∀n P(n)",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"160\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">primul cade → fiecare treaptă îl doboară pe următorul</text><rect x=\"20\" y=\"140\" width=\"40\" height=\"20\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"40\" y=\"154\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">0</text><rect x=\"70\" y=\"120\" width=\"40\" height=\"40\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"90\" y=\"144\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">1</text><rect x=\"120\" y=\"95\" width=\"40\" height=\"65\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"140\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">2</text><rect x=\"170\" y=\"70\" width=\"40\" height=\"90\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"190\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">3</text><path d=\"M220 80 Q260 40 300 60\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\" marker-end=\"url(#arri)\"/><defs><marker id=\"arri\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#c8922a\"/></marker></defs><text x=\"270\" y=\"45\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\">și tot așa...</text></svg>",intuitiv_text:"<span class=\"hl\">Ca un șir de domino</span>: dacă primul cade (P(0) adevărat) și fiecare domino care cade îl doboară pe următorul (P(n)→P(n+1)), atunci toate dominourile cad, oricât de lung ar fi șirul.",intuitiv_nota:"Ideea apare implicit la Euclid și e folosită de Pascal (1665) în triunghiul lui Pascal, dar formalizarea riguroasă ca axiomă vine de la Giuseppe Peano (1889), în axiomatizarea numerelor naturale. Este echivalentă cu principiul bunei ordonări a lui ℕ.",exercitii:[{"q":"Demonstrează prin inducție matematică faptul că 1+2+...+n = n(n+1)/2, pentru orice număr natural n≥1.","pasi":["Pasul de bază: pentru n=1, suma este chiar 1, iar formula dă 1·2/2=1, deci afirmația este adevărată pentru primul caz.","Pasul inductiv - presupunem că formula e adevărată pentru un k oarecare, adică 1+2+...+k=k(k+1)/2, și trebuie să arătăm că e adevărată și pentru k+1.","Adunând (k+1) la ambele părți ale ipotezei, obținem 1+2+...+k+(k+1)=k(k+1)/2+(k+1)=(k+1)(k+2)/2, exact formula pentru n=k+1, deci treapta următoare cade la rândul ei."],"r":"✓ Formula este adevărată pentru orice n≥1, prin inducție matematică completă."},{"q":"Ce s-ar întâmpla dacă am demonstra doar pasul de bază P(0), fără a demonstra vreodată implicația P(n)→P(n+1)?","pasi":["Faptul că P(0) este adevărată nu ne spune absolut nimic, prin el însuși, despre P(1), P(2) sau despre oricare alt caz ulterior.","Fără implicația P(n)→P(n+1), lanțul de adevăr se poate rupe oriunde, la orice pas ulterior, fără ca noi să avem vreun mijloc de a-l detecta.","Practic am avea doar un prim domino căzut, fără nicio garanție că va doborî vreun alt domino din șir - concluzia P(n) pentru toți n nu ar mai putea fi trasă."],"r":"✓ Nu am putea concluziona nimic despre n≥1 - fără pasul inductiv, adevărul nu se propagă mai departe."},{"q":"Găsește eroarea din argumentul „prin inducție toți caii dintr-un grup au aceeași culoare”: presupunem că orice n cai au aceeași culoare, luăm n+1 cai, îi împărțim în două grupe suprapuse de câte n cai, și concluzionăm că toți n+1 au aceeași culoare.","pasi":["Pasul inductiv din acest argument presupune tacit că cele două grupe de n cai, obținute prin eliminarea pe rând a câte unui cal, au întotdeauna cel puțin un cal comun, prin care „leagă” culorile celor două grupe.","Această presupunere este adevărată pentru grupe cu trei sau mai mulți cai, dar eșuează exact la trecerea de la n=1 la n=2: cele două grupe de câte un singur cal nu au niciun cal comun între ele.","Deci pasul inductiv se rupe chiar la început, la n=1→2, iar concluzia falsă (toți caii au aceeași culoare) nu urmează de nicăieri, oricât de convingător ar părea restul argumentului."],"r":"✓ Argumentul este greșit - pasul inductiv eșuează exact la n=1→2, unde grupele nu se intersectează."},{"q":"Adevărat sau fals: inducția tare (în care presupunem P(0), P(1), ..., P(k) pentru a demonstra P(k+1)) este o metodă de demonstrație logic mai puternică decât inducția simplă.","pasi":["Fals ca afirmație de putere logică absolută - se poate arăta că inducția tare și inducția simplă sunt echivalente, fiecare putând fi dedusă riguros din cealaltă.","Diferența dintre ele este mai degrabă practică: inducția tare este mai comodă atunci când P(k+1) depinde nu doar de cazul imediat anterior P(k), ci de mai multe cazuri anterioare la un loc.","Un exemplu tipic este demonstrarea unor proprietăți despre numere prime sau despre descompuneri, unde e nevoie de toate cazurile mai mici, nu doar de cel imediat precedent."],"r":"✓ Fals ca putere logică - sunt echivalente; diferă doar în comoditatea aplicării practice."},{"q":"De ce funcțiile recursive din programare, care se apelează pe ele însele pentru o valoare mai mică, se bazează pe aceeași idee ca inducția matematică pentru a fi corecte?","pasi":["O funcție recursivă are, de obicei, un caz de bază simplu, care se rezolvă direct, exact ca pasul de bază P(0) din inducție.","Pentru celelalte cazuri, funcția presupune (prin apelul recursiv) că versiunea ei pentru o valoare mai mică funcționează corect, și construiește pe baza ei rezultatul pentru valoarea curentă - exact ca pasul inductiv P(n)→P(n+1).","Corectitudinea întregii funcții recursive, pentru orice valoare de intrare, se demonstrează formal exact prin principiul inducției matematice aplicat pașilor ei."],"r":"✓ Pentru că un caz de bază plus un pas recursiv corect reproduc exact structura demonstrației prin inducție."}]};
CONTINUT_LOGICA["tabele-de-adevar-completitudine"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Calculul propozițional este complet: pentru orice formulă φ, φ este o tautologie (adevărată în orice interpretare, verificabilă prin tabel de adevăr) dacă și numai dacă φ este demonstrabilă formal, folosind axiomele și regulile de deducție ale sistemului.</div>",formula_display:"⊨φ ↔ ⊢φ (pentru calculul propozițional)",diagrama:"<svg viewBox=\"0 0 300 190\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"150\" y1=\"40\" x2=\"150\" y2=\"70\" stroke=\"#8a3010\" stroke-width=\"3\"/><polygon points=\"150,70 120,110 180,110\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><line x1=\"40\" y1=\"55\" x2=\"260\" y2=\"55\" stroke=\"#8a3010\" stroke-width=\"3\"/><line x1=\"60\" y1=\"55\" x2=\"60\" y2=\"90\" stroke=\"#8a3010\" stroke-width=\"1.5\"/><line x1=\"240\" y1=\"55\" x2=\"240\" y2=\"90\" stroke=\"#8a3010\" stroke-width=\"1.5\"/><path d=\"M30 90 Q60 115 90 90\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><path d=\"M210 90 Q240 115 270 90\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"60\" y=\"30\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">adevărat ⊨φ</text><text x=\"240\" y=\"30\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\">demonstrabil ⊢φ</text><text x=\"150\" y=\"172\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">balanța stă mereu în echilibru perfect</text></svg>",intuitiv_text:"Ai o balanță cu două talere. Pe un taler pui toate propozițiile care sunt <em>mereu</em> adevărate, oricum ai aranja A și F în tabelul de adevăr. Pe celălalt taler pui toate propozițiile pe care le poți <em>demonstra</em>, pas cu pas, din regulile logicii. <span class=\"hl\">Balanța stă mereu perfect în echilibru: exact aceleași propoziții sunt pe ambele talere, niciodată una fără cealaltă</span>.",intuitiv_nota:"Rezultatul a fost demonstrat riguros de Emil Post (1921); ideea e prezentă implicit și în lucrările lui Frege și Russell-Whitehead. Diferă esențial de aritmetică: calculul propozițional e atât complet, cât și decidabil (prin tabele de adevăr finite), spre deosebire de aritmetica lui Gödel, care e incompletă.",exercitii:[{"q":"Arată, folosind tabelul de valori de adevăr, că formula φ=(P→P) este o tautologie, și explică ce spune teorema de completitudine despre acest fapt.","pasi":["Pentru P=adevărat, P→P devine adevărat→adevărat, care este adevărat prin definiția implicației.","Pentru P=fals, P→P devine fals→fals, care este de asemenea adevărat, pentru că o implicație cu premisă falsă este mereu adevărată.","Cum φ este adevărată în ambele linii posibile ale tabelului de adevăr, φ este o tautologie (⊨φ), iar teorema de completitudine ne garantează că există și o demonstrație formală a ei (⊢φ)."],"r":"✓ φ este o tautologie, deci, prin completitudine, este și demonstrabilă formal."},{"q":"Ce s-ar întâmpla dacă am descoperi o formulă φ care este tautologie (adevărată în orice interpretare) dar care nu poate fi demonstrată din axiomele calculului propozițional?","pasi":["O asemenea descoperire ar contrazice direct teorema de completitudine, care afirmă exact echivalența ⊨φ ↔ ⊢φ pentru calculul propozițional.","Ar însemna fie că sistemul de axiome și reguli de deducție este prea slab pentru a captura tot ce e adevărat semantic, fie că am greșit undeva verificarea tautologiei sau a demonstrației.","Deoarece completitudinea calculului propozițional este demonstrată riguros (Post, 1921), o asemenea formulă „rebelă” nu poate exista de fapt - orice tautologie are garantat o demonstrație."],"r":"✓ Nu poate exista o asemenea formulă - completitudinea garantează că orice tautologie e demonstrabilă."},{"q":"Calculul propozițional este atât complet, cât și decidabil (prin tabele de adevăr finite). De ce nu intră acest fapt în contradicție cu incompletitudinea lui Gödel?","pasi":["Teorema lui Gödel se aplică doar sistemelor formale suficient de puternice pentru a reprezenta aritmetica elementară, cu adunare, înmulțire și cuantificatori peste numerele naturale.","Calculul propozițional nu are deloc cuantificatori și nu poate exprima enunțuri aritmetice precum „pentru orice număr natural n...”, deci condițiile teoremei lui Gödel pur și simplu nu i se aplică.","De aceea calculul propozițional poate fi, fără contradicție, complet și decidabil, în timp ce aritmetica, mult mai expresivă, este incompletă."],"r":"✓ Nu se contrazic - calculul propozițional e prea slab pentru a satisface ipotezele teoremei lui Gödel."},{"q":"Adevărat sau fals: formula ψ=(P∧¬P) este demonstrabilă în calculul propozițional, conform teoremei de completitudine.","pasi":["Fals - ψ afirmă simultan P și negația lui P, deci este falsă în orice interpretare posibilă a lui P, fie el adevărat sau fals.","Fiind falsă în orice interpretare, ψ nu este o tautologie (⊭ψ), ci mai degrabă o contradicție.","Teorema de completitudine leagă tautologiile de propozițiile demonstrabile, deci din ⊭ψ rezultă ⊬ψ - ψ nu este demonstrabilă, deși negația ei, ¬ψ, este."],"r":"✓ Fals - ψ este o contradicție, nu o tautologie, deci nu este demonstrabilă."},{"q":"Ce garantează teorema de completitudine, combinată cu decidabilitatea prin tabele de adevăr, pentru un program de calculator care verifică automat formule de logică propozițională?","pasi":["Decidabilitatea prin tabele de adevăr finite garantează că, pentru orice formulă, un program poate verifica mecanic, într-un număr finit de pași, dacă ea este sau nu tautologie.","Completitudinea garantează, în plus, că orice formulă găsită tautologie are și o demonstrație formală corespunzătoare, deci programul nu va rata niciodată vreun adevăr logic din cauza slăbiciunii sistemului de deducție.","Împreună, cele două proprietăți fac din verificarea formulelor de logică propozițională o problemă complet rezolvabilă algoritmic, spre deosebire de aritmetica generală."],"r":"✓ Garantează că orice tautologie poate fi găsită și confirmată automat, într-un număr finit de pași."}]};
CONTINUT_LOGICA["teorema-lui-church-turing"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Teza (nu o teoremă demonstrabilă matematic) afirmă că orice funcție calculabilă în sens intuitiv, printr-o procedură efectivă, algoritmică, poate fi calculată de o mașină Turing - echivalent, este o funcție recursivă, sau exprimabilă în calculul lambda.</div>",formula_display:"Calculabil intuitiv (algoritm) ↔ calculabil de mașină Turing",diagrama:"<svg viewBox=\"0 0 320 190\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"20\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"55\" y=\"40\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a3010\">algoritm intuitiv</text><rect x=\"130\" y=\"20\" width=\"70\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"165\" y=\"40\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a3010\">mașină Turing</text><rect x=\"240\" y=\"20\" width=\"60\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"270\" y=\"40\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">calcul λ</text><line x1=\"55\" y1=\"50\" x2=\"140\" y2=\"100\" stroke=\"#8a3010\" stroke-width=\"1.5\"/><line x1=\"165\" y1=\"50\" x2=\"165\" y2=\"100\" stroke=\"#8a3010\" stroke-width=\"1.5\"/><line x1=\"270\" y1=\"50\" x2=\"190\" y2=\"100\" stroke=\"#8a3010\" stroke-width=\"1.5\"/><circle cx=\"160\" cy=\"128\" r=\"38\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"3\"/><text x=\"160\" y=\"124\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">aceeași clasă</text><text x=\"160\" y=\"137\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">de funcții</text><text x=\"160\" y=\"182\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">toate drumurile duc la același „calculabil”</text></svg>",intuitiv_text:"Mulți oameni au încercat să descrie, în feluri foarte diferite, ce înseamnă „a calcula ceva după o rețetă exactă”: unii au desenat un robot cu o bandă de hârtie și simboluri, alții au scris rețete matematice abstracte cu litere și paranteze. <span class=\"hl\">Surprinzător, toate aceste descrieri s-au dovedit a fi exact același lucru, doar îmbrăcat altfel</span>. De aceea credem că am prins, în sfârșit, ideea adevărată de „algoritm” - deși nu putem demonstra asta ca pe o teoremă obișnuită, pentru că nu am definit matematic ce înseamnă „intuitiv”.",intuitiv_nota:"Alonzo Church (1936, prin calculul lambda) și Alan Turing (1936, prin mașini Turing) au propus independent formalizări echivalente ale noțiunii intuitive de „algoritm”. Fiind o teză, nu o teoremă, nu poate fi demonstrată riguros (noțiunea de „calculabil intuitiv” nu are o definiție matematică precisă), dar nu a fost niciodată infirmată și stă la baza întregii informatici teoretice.",exercitii:[{"q":"Mașinile Turing, calculul lambda al lui Church și funcțiile recursive ale lui Gödel-Herbrand au fost propuse independent, ca formalizări diferite ale ideii de „calcul”. Ce relație riguroasă s-a demonstrat matematic între ele?","pasi":["Deși cele trei modele arată foarte diferit - benzi și simboluri la Turing, funcții și substituții la Church, ecuații recursive la Gödel-Herbrand - s-a demonstrat matematic, riguros, că definesc exact aceeași clasă de funcții calculabile.","Echivalența aceasta e ea însăși o teoremă obișnuită, demonstrată complet - spre deosebire de teza Church-Turing în sine.","Convergența independentă a trei abordări atât de diferite spre aceeași clasă de funcții este principalul argument, empiric dar foarte puternic, pentru a accepta teza Church-Turing."],"r":"✓ S-a demonstrat că sunt echivalente matematic - definesc exact aceeași clasă de funcții calculabile."},{"q":"Ce s-ar întâmpla, pentru teza Church-Turing, dacă s-ar descoperi vreodată un dispozitiv fizic (cuantic sau de alt tip) care calculează o funcție imposibil de calculat de orice mașină Turing?","pasi":["O asemenea descoperire ar infirma direct teza Church-Turing, arătând că noțiunea intuitivă de „calculabil” este mai largă decât clasa funcțiilor calculabile Turing.","Până acum, calculatoarele cuantice, deși pot fi dramatic mai rapide pentru anumite probleme, nu au calculat niciodată o funcție nouă, în afara clasei Turing - doar aceeași clasă, cu altă viteză.","Teza rămâne, deci, doar o presupunere puternic susținută de dovezi, niciodată demonstrată ca teoremă și niciodată infirmată experimental sau teoretic până acum."],"r":"✓ Teza Church-Turing ar fi infirmată - dar până acum nu s-a găsit niciun asemenea dispozitiv."},{"q":"Problema opririi (Halting Problem) arată că nicio mașină Turing nu poate calcula funcția HALT. Ce spune teza Church-Turing despre existența unui alt tip de „algoritm”, non-Turing, care ar rezolva totuși Halting?","pasi":["Acceptând teza Church-Turing, orice procedură care ar putea fi descrisă, intuitiv, drept „algoritmică” trebuie să fie echivalentă cu o mașină Turing, indiferent de forma ei exterioară.","Cum s-a demonstrat riguros (aceasta chiar este o teoremă) că nicio mașină Turing nu poate calcula HALT pentru orice pereche program-input, rezultă, prin teză, că niciun algoritm intuitiv nu poate face asta.","Așa se interpretează, de altfel, rezultatul în informatica teoretică: Halting Problem nu e doar „greu”, ci imposibil de rezolvat algoritmic, în orice sens rezonabil al cuvântului „algoritm”."],"r":"✓ Niciun algoritm, în sensul intuitiv acceptat de teză, nu poate rezolva Halting Problem."},{"q":"Adevărat sau fals: teza Church-Turing este o teoremă demonstrată riguros, la fel cum este demonstrată teorema lui Pitagora.","pasi":["Fals - o demonstrație riguroasă ar cere compararea a două noțiuni matematic precise, dar „calculabil în mod intuitiv, printr-o procedură efectivă” nu are o definiție matematică formală.","Ce se poate demonstra riguros este doar echivalența dintre diferitele modele formale propuse (Turing, Church, funcții recursive) - aceea este o teoremă adevărată.","Legătura dintre acea clasă formală și ideea informală de „algoritm” rămâne o teză empirică, susținută de dovezi puternice, dar niciodată demonstrată ca teoremă matematică."],"r":"✓ Fals - este o teză susținută de dovezi puternice, nu o teoremă demonstrată matematic."},{"q":"De ce faptul că Python, Java, C++ și orice alt limbaj de programare general au aceeași putere de calcul (sunt Turing-complete) este o consecință directă a teoremei de echivalență din spatele tezei Church-Turing?","pasi":["Fiecare limbaj de programare general poate simula o mașină Turing, și, reciproc, o mașină Turing poate simula orice program scris în acel limbaj, folosind suficientă memorie și timp.","Practic, toate aceste limbaje calculează aceeași clasă de funcții - nimic ce poți calcula în unul nu devine imposibil de calculat în celălalt, doar mai simplu sau mai greoi de scris.","De aceea alegerea unui limbaj de programare este, teoretic, o chestiune de exprimare și eficiență practică, nu una de putere brută de calcul - toate limbajele general-utilizabile sunt, în acest sens, la fel de puternice."],"r":"✓ Pentru că toate simulează reciproc o mașină Turing, deci au exact aceeași putere de calcul."}]};
CONTINUT_LOGICA["paradoxul-lui-russell"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie R mulțimea tuturor mulțimilor care nu se conțin pe ele însele ca element: R={x : x∉x}. Întrebarea „R∈R?” duce la o contradicție logică în ambele cazuri posibile, arătând că teoria naivă a mulțimilor, cu principiul comprehensiunii nerestricționate, este inconsistentă.</div>",formula_display:"R={x : x∉x} → (R∈R ↔ R∉R), contradicție",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"150\" cy=\"95\" r=\"55\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"150\" y=\"75\" text-anchor=\"middle\" font-size=\"14\" fill=\"#8a3010\">R</text><path d=\"M150 40 A 55 55 0 0 1 205 95\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"4 3\" marker-end=\"url(#arrr)\"/><defs><marker id=\"arrr\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#c8922a\"/></marker></defs><text x=\"235\" y=\"65\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">R∈R?</text><line x1=\"210\" y1=\"50\" x2=\"230\" y2=\"70\" stroke=\"#8a3010\" stroke-width=\"3\"/><line x1=\"230\" y1=\"50\" x2=\"210\" y2=\"70\" stroke=\"#8a3010\" stroke-width=\"3\"/><text x=\"150\" y=\"155\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">„R conține tot ce nu se conține pe sine”</text><text x=\"150\" y=\"172\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">ambele răspunsuri duc la contradicție</text></svg>",intuitiv_text:"<span class=\"hl\">Bărbierul satului bărbierește pe toți cei care nu se bărbieresc singuri - dar cine îl bărbierește pe bărbier?</span> Dacă se bărbierește singur, atunci nu ar trebui, căci bărbierește doar pe cei care nu o fac singuri; dacă nu se bărbierește singur, atunci ar trebui, conform aceleiași reguli. Ambele variante duc la contradicție - exact structura paradoxului lui Russell.",intuitiv_nota:"Bertrand Russell (1901) a descoperit paradoxul examinând fundamentele teoriei mulțimilor ale lui Cantor și Frege, chiar când Frege termina al doilea volum al operei sale fundamentale, Grundgesetze der Arithmetik. Russell i-a scris lui Frege, dezvăluind paradoxul chiar înainte de publicare, iar Frege a adăugat o notă recunoscând că fundația teoriei sale se prăbușește. Descoperirea a dus la teoria axiomatică a mulțimilor (ZFC), care restricționează principiul comprehensiunii tocmai pentru a evita astfel de paradoxuri.",exercitii:[{"q":"Fie R={x : x∉x} mulțimea tuturor mulțimilor care nu se conțin pe ele însele. Presupune că R∈R și arată, pas cu pas, ce contradicție rezultă.","pasi":["Presupunem că R∈R, adică R este ea însăși un element al mulțimii R.","Dar orice element al lui R trebuie să satisfacă, prin definiția lui R, condiția x∉x - adică să nu se conțină pe sine.","Aplicând această condiție chiar lui R, obținem R∉R, ceea ce contrazice direct presupunerea inițială R∈R."],"r":"✓ Presupunerea R∈R duce, prin definiția lui R, direct la R∉R - o contradicție."},{"q":"Ce s-ar întâmpla dacă am insista să păstrăm teoria naivă a mulțimilor, cu principiul comprehensiunii nerestricționate ({x : P(x)} este mereu o mulțime, pentru orice proprietate P), în ciuda paradoxului lui Russell?","pasi":["Am putea forma și R={x : x∉x} ca mulțime validă, la fel ca orice altă proprietate P, pentru că principiul nu impune nicio restricție.","Dar am arătat deja că presupunerea existenței lui R duce la contradicție logică, indiferent de răspunsul dat întrebării „R∈R?”.","Într-un sistem în care apare o contradicție, prin regulile logicii clasice se poate demonstra orice afirmație, adevărată sau falsă - întreaga teorie ar deveni inutilă, nu doar greșită într-un punct izolat."],"r":"✓ Teoria ar deveni inconsistentă, iar dintr-o contradicție se poate demonstra orice - deci complet inutilă ca fundație."},{"q":"Analogia bărbierului: „bărbierul din sat bărbierește exact pe toți sătenii care nu se bărbieresc singuri.” Poate exista, în realitate, un asemenea bărbier, sătean el însuși?","pasi":["Dacă bărbierul s-ar bărbieri singur, atunci, conform regulii, el ar fi cineva care se bărbierește singur, deci nu ar trebui să se afle printre cei pe care îi bărbierește - contradicție.","Dacă bărbierul nu s-ar bărbieri singur, atunci, conform aceleiași reguli, el ar trebui să fie bărbierit de bărbier - adică de el însuși - din nou contradicție.","Concluzia corectă nu este că paradoxul rămâne nerezolvat, ci că un asemenea bărbier, cu exact această regulă, pur și simplu nu poate exista în realitate."],"r":"✓ Un asemenea bărbier nu poate exista - regula lui este auto-contradictorie, la fel ca definiția lui R."},{"q":"Adevărat sau fals: paradoxul lui Russell arată o greșeală de calcul izolată în teoria lui Cantor, ușor de reparat printr-o mică ajustare locală.","pasi":["Fals - paradoxul nu este o simplă greșeală de calcul, ci o consecință logică inevitabilă a principiului comprehensiunii nerestricționate, aplicat oricărei proprietăți exprimabile.","Reparația a necesitat regândirea fundamentală a felului în care se pot forma mulțimile, nu doar corectarea unui singur exemplu problematic.","Rezultatul a fost teoria axiomatică ZFC, care înlocuiește complet comprehensiunea liberă cu axiome mult mai restrictive, printre care axioma separării."],"r":"✓ Fals - a necesitat reconstrucția fundamentală a teoriei mulțimilor, nu o simplă reparație locală."},{"q":"De ce sistemele de tipuri din limbajele de programare moderne (care interzic, de exemplu, ca o listă să se conțină direct pe ea însăși ca element, fără indirecție) sunt înrudite cu soluția lui Russell la propriul paradox?","pasi":["Paradoxul lui Russell a arătat că auto-referința nerestricționată (o mulțime care se conține sau nu se conține pe sine) poate produce contradicții logice.","Russell însuși a propus, ca soluție timpurie, teoria tipurilor - o ierarhie în care un obiect de un anumit tip nu poate conține direct un obiect de același tip sau de un tip superior.","Multe limbaje de programare moderne moștenesc această idee prin sistemele lor de tipuri, care interzic anumite forme de auto-referință directă, tocmai pentru a evita comportamente contradictorii sau bucle infinite la nivel de structură de date."],"r":"✓ Pentru că moștenesc, prin sistemele de tipuri, ideea lui Russell de a interzice auto-referința nerestricționată."}]};
CONTINUT_LOGICA["teorema-lui-tarski-nedefinibilitate"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Nu există nicio formulă aritmetică True(n) în limbajul aritmeticii de ordinul întâi care să definească adevărul: adică astfel încât, pentru orice formulă φ cu numărul Gödel ⌜φ⌝, să avem True(⌜φ⌝) adevărată dacă și numai dacă φ este adevărată.</div>",formula_display:"Nu ∃ formulă aritmetică True(n) astfel încât True(⌜φ⌝) ↔ φ, pentru orice φ",diagrama:"<svg viewBox=\"0 0 300 170\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a3010\">nicio formulă aritmetică nu poate defini adevărul</text><rect x=\"90\" y=\"40\" width=\"120\" height=\"60\" rx=\"8\" fill=\"none\" stroke=\"#8a3010\" stroke-width=\"2\"/><text x=\"150\" y=\"75\" text-anchor=\"middle\" font-size=\"14\" fill=\"#8a3010\">True(n)</text><line x1=\"90\" y1=\"40\" x2=\"210\" y2=\"100\" stroke=\"#c8922a\" stroke-width=\"3\"/><line x1=\"210\" y1=\"40\" x2=\"90\" y2=\"100\" stroke=\"#c8922a\" stroke-width=\"3\"/><text x=\"150\" y=\"128\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">„această propoziție e falsă” → contradicție</text><text x=\"150\" y=\"148\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a3010\">dacă True(n) ar exista</text></svg>",intuitiv_text:"Imaginează o carte care ar vrea să spună, chiar ea despre ea însăși, „tot ce scrie în mine e verificat corect, adevărat sau fals”. Scriem în ea o propoziție ascunsă: <span class=\"hl\">„Această propoziție din carte este falsă.”</span> Dacă cartea spune că propoziția e adevărată, atunci ea chiar e falsă, cum zice; dacă spune că e falsă, atunci exact asta zice propoziția, deci e adevărată. Niciun răspuns nu funcționează - de aceea nicio carte, niciun limbaj matematic, nu-și poate defini complet, din interior, propriul adevăr.",intuitiv_nota:"Alfred Tarski (1936) a demonstrat rezultatul folosind aceeași tehnică de auto-referință, prin numerotare Gödel, ca și Gödel în 1931. Rezultatul e strâns înrudit cu incompletitudinea lui Gödel, dar diferă: Gödel arată că unele adevăruri nu sunt demonstrabile, Tarski arată că noțiunea de „adevăr” în sine nu poate fi exprimată în limbajul propriu al aritmeticii - pentru a vorbi despre adevărul aritmeticii ai nevoie de un metalimbaj mai bogat.",exercitii:[{"q":"Presupunând că True(n) ar exista, arată, folosind lema diagonală, cum se construiește o propoziție „mincinoasă” L, cu numărul Gödel ⌜L⌝, astfel încât L să fie echivalentă cu ¬True(⌜L⌝).","pasi":["Lema diagonală, folosită și de Gödel în 1931, spune că pentru orice formulă φ(x) cu o variabilă liberă există o propoziție L astfel încât L este echivalentă cu φ(⌜L⌝), numărul Gödel al lui L însuși.","Aplicăm lema diagonală formulei φ(x)=¬True(x), obținând o propoziție L echivalentă cu ¬True(⌜L⌝).","Cu alte cuvinte, L spune despre ea însăși, prin acest ocol aritmetic, exact „eu nu sunt adevărată” - varianta aritmetică a clasicului paradox al mincinosului."],"r":"✓ Se obține L echivalentă cu ¬True(⌜L⌝), construită prin lema diagonală a lui Gödel."},{"q":"Ce s-ar întâmpla dacă True(n) ar exista cu adevărat și ar defini corect adevărul, adică True(⌜φ⌝) ar fi echivalent cu φ pentru orice formulă φ, inclusiv pentru L de mai sus?","pasi":["Aplicând proprietatea de definire corectă a lui True chiar propoziției L, am obține că L este echivalentă cu True(⌜L⌝).","Dar am construit deja L astfel încât L să fie echivalentă cu ¬True(⌜L⌝) - combinând cele două echivalențe, obținem True(⌜L⌝) echivalent cu ¬True(⌜L⌝).","Aceasta este o contradicție logică directă (o propoziție echivalentă cu propria ei negație), deci presupunerea inițială - că True(n) există și definește corect adevărul - trebuie abandonată."],"r":"✓ S-ar ajunge la o contradicție logică directă, deci True(n) nu poate exista."},{"q":"Predicatul de demonstrabilitate Prov(n) al lui Gödel este definibil aritmetic, spre deosebire de True(n). De ce nu duce Prov la aceeași contradicție ca predicatul de adevăr True?","pasi":["Prov(n) poate fi construit efectiv, în mod explicit, ca o formulă aritmetică obișnuită - Gödel a făcut chiar această construcție în 1931.","Diferența esențială este că Prov(⌜φ⌝) nu este echivalent logic cu φ pentru orice formulă φ, așa cum ar fi cerut de o definiție corectă a adevărului pentru True.","Demonstrabilitatea este o noțiune pur sintactică, despre existența unui șir de pași de deducție, mai slabă decât adevărul semantic - această slăbiciune este exact ce permite lui Prov să fie definibil fără contradicție."],"r":"✓ Pentru că Prov este o noțiune sintactică mai slabă decât adevărul semantic - nu cere echivalența Prov(⌜φ⌝)↔φ pentru orice φ."},{"q":"Adevărat sau fals: teorema lui Tarski despre nedefinibilitatea adevărului și prima teoremă de incompletitudine a lui Gödel sunt, în esență, același rezultat, doar formulat diferit.","pasi":["Fals - deși ambele folosesc aceeași tehnică de auto-referință, prin numerotare Gödel și lema diagonală, cele două rezultate afirmă lucruri diferite.","Gödel arată că există propoziții adevărate dar nedemonstrabile într-un sistem consistent - o afirmație despre relația dintre adevăr (⊨) și demonstrabilitate (⊢).","Tarski arată ceva mai radical: că noțiunea de adevăr aritmetic în sine nu poate fi exprimată deloc printr-o formulă a limbajului aritmeticii - o afirmație despre exprimabilitate, nu despre demonstrabilitate."],"r":"✓ Fals - sunt rezultate diferite, deși înrudite și demonstrate prin aceeași tehnică de auto-referință."},{"q":"De ce un program de calculator care ar dori să implementeze o funcție „este_adevărată(enunț)” pentru orice enunț matematic posibil se lovește, în principiu, de teorema lui Tarski?","pasi":["O funcție „este_adevărată” perfectă, care să răspundă corect pentru orice enunț aritmetic exprimat în limbajul aritmeticii, ar corespunde exact predicatului True(n) din teorema lui Tarski.","Teorema arată că un asemenea predicat nu poate fi definit consistent chiar în interiorul limbajului aritmeticii, oricât de sofisticat ar fi programul care încearcă să-l implementeze.","În practică, verificatoarele automate de teoreme ocolesc problema lucrând cu noțiunea mai slabă de demonstrabilitate într-un sistem formal fixat, nu cu noțiunea absolută, universală, de adevăr."],"r":"✓ Pentru că un asemenea program ar implementa exact predicatul True(n), imposibil de definit consistent, conform teoremei lui Tarski."}]};
